#!/usr/bin/env node
"use strict";

// Étape 43a : restauration d'une sauvegarde Oracle (fichier JSON, 13 tables).
// - DRY-RUN par défaut, --apply pour écrire.
// - Refus : somme de contrôle incorrecte, format/version inconnus, base cible
//   non vide, NODE_ENV=production sans --apply explicite.
// - Écriture : ids d'origine conservés (INSERT explicite de l'id), identités
//   GENERATED BY DEFAULT ré-alignées pour que les prochains ids ne heurtent
//   pas les ids restaurés, insertion dans l'ordre des clés étrangères,
//   une seule transaction (annulation complète en cas d'erreur, sans retry).
// - Requêtes : liaisons de paramètres uniquement ; les noms de table et de
//   colonne viennent de la constante TABLES, la valeur de l'identité est liée
//   (Oracle refuse les liaisons dans le DDL : EXECUTE IMMEDIATE + :depart).
// - Aucun identifiant ni mot de passe dans les journaux.
//
// Usage : node src/scripts/restore-oracle.js <fichier> [--apply]

import { existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

import { loadConfig } from '../config.js';
import {
  TABLES,
  compterTables,
  lireFichierBackup,
  maxIdSection,
  nomServiceOracle,
} from './backup-oracle.js';
import { closeOracle, getKnex, messageErreurOracle } from '../db/oracle.js';

export function analyserArgs(argv) {
  const options = { apply: false, fichier: null };
  const erreurs = [];
  for (const arg of argv) {
    if (arg === '--apply') {
      options.apply = true;
      continue;
    }
    if (arg.startsWith('--')) {
      erreurs.push(`Option inconnue : ${arg}`);
      continue;
    }
    if (options.fichier !== null) {
      erreurs.push(`Argument inattendu : ${arg}`);
      continue;
    }
    options.fichier = arg;
  }
  if (options.fichier === null) erreurs.push('Fichier de sauvegarde attendu.');
  return { ...options, erreurs };
}

// Refus purs, testables sans base.
export function messageRefusProduction(nodeEnv, apply) {
  if (nodeEnv === 'production' && !apply) {
    return 'Restauration Oracle refusée en production sans --apply explicite.';
  }
  return null;
}

export function messageCibleNonVide(tablesNonVides) {
  if (!Array.isArray(tablesNonVides) || tablesNonVides.length === 0) return null;
  return (
    `Cible Oracle non vide (${tablesNonVides.join(', ')}) : ` +
    'la restauration ne porte que sur une base vidée (npm run oracle:schema -- --reset en développement, ' +
    'une cible neuve en production).'
  );
}

export function messageRefusFichier(erreurs) {
  if (!Array.isArray(erreurs) || erreurs.length === 0) return null;
  return ['Fichier de sauvegarde refusé :', ...erreurs.map((erreur) => `  - ${erreur}`)].join('\n');
}

function sectionDe(fichier, nomTable) {
  return fichier.tables.find((section) => section.name === nomTable);
}

// Une valeur du fichier → valeur à lier : ISO 8601 → Date (les colonnes
// TIMESTAMP WITH TIME ZONE refusent une chaîne), JSON → chaîne JSON.
export function valeurPourBind(valeur, type, nomTable) {
  if (valeur === undefined || valeur === null) return null;
  if (type === 'date') {
    const date = valeur instanceof Date ? valeur : new Date(valeur);
    if (Number.isNaN(date.getTime())) {
      throw new Error(`Date invalide dans ${nomTable} : ${JSON.stringify(valeur)}`);
    }
    return date;
  }
  if (type === 'json') {
    return typeof valeur === 'string' ? valeur : JSON.stringify(valeur);
  }
  return valeur;
}

// Ré-aligne chaque identité au-dessus du plus grand id restauré : le prochain
// id généré est alors maxId + 1 (un identifiant plus bas entrerait en collision
// avec les ids réécrits). La valeur est liée (voir en-tête du fichier).
export async function alignerIdentites(db, fichier) {
  for (const definition of TABLES) {
    if (!definition.identite) continue;
    const maxId = maxIdSection(sectionDe(fichier, definition.nom));
    if (maxId === null) continue;
    const depart = maxId + 1;
    if (!Number.isSafeInteger(depart) || depart < 1) {
      throw new Error(`Id maximal invalide pour ${definition.nom} : ${JSON.stringify(maxId)}`);
    }
    await db.raw(
      `BEGIN EXECUTE IMMEDIATE 'ALTER TABLE ${definition.nom} ` +
        `MODIFY ID GENERATED BY DEFAULT AS IDENTITY (START WITH ' || :depart || ')'; END;`,
      { depart }
    );
  }
}

// Toutes les lignes du fichier, table par table dans l'ordre des clés
// étrangères, dans UNE SEULE transaction : la moindre erreur annule tout.
export async function insererTout(db, fichier) {
  return db.transaction(async (trx) => {
    let total = 0;
    for (const definition of TABLES) {
      const section = sectionDe(fichier, definition.nom);
      const noms = definition.colonnes.map((colonne) => colonne.nom);
      const sql =
        `INSERT INTO ${definition.nom} (${noms.join(', ')}) ` +
        `VALUES (${definition.colonnes.map(() => '?').join(', ')})`;
      for (const ligne of section.rows) {
        const valeurs = definition.colonnes.map((colonne) =>
          valeurPourBind(ligne[colonne.nom], colonne.type, definition.nom)
        );
        await trx.raw(sql, valeurs);
        total += 1;
      }
    }
    return total;
  });
}

function afficherPlan(fichier) {
  console.log('Plan de restauration :');
  for (const definition of TABLES) {
    const section = sectionDe(fichier, definition.nom);
    const maxId = maxIdSection(section);
    console.log(
      `  ${definition.nom.padEnd(21)} : ${section.rows.length} ligne(s)` +
        (maxId === null ? '' : `, id max ${maxId}`)
    );
  }
}

export async function main(argv = process.argv.slice(2), nodeEnv = process.env.NODE_ENV) {
  const { apply, fichier: fichierArg, erreurs } = analyserArgs(argv);
  if (erreurs.length > 0) {
    for (const erreur of erreurs) console.error(erreur);
    console.error('');
    console.error('Usage : node src/scripts/restore-oracle.js <fichier> [--apply]');
    return 1;
  }

  const chemin = resolve(fichierArg);
  if (!existsSync(chemin)) {
    console.error(`Fichier introuvable : ${chemin}`);
    return 1;
  }

  const lecture = lireFichierBackup(chemin);
  if (!lecture.ok) {
    const refus = messageRefusFichier(lecture.erreurs);
    console.error(refus);
    return 1;
  }
  const fichier = lecture.fichier;

  const refusProduction = messageRefusProduction(nodeEnv, apply);
  if (refusProduction) {
    console.error(refusProduction);
    return 1;
  }

  const config = loadConfig();
  const service = nomServiceOracle(config);
  console.log(`Fichier de sauvegarde : ${chemin}`);
  console.log(`Service : ${service}`);
  console.log(`Date de la sauvegarde : ${fichier.date}`);
  console.log(`Somme de contrôle SHA-256 : ${fichier.sha256} (vérifiée)`);

  try {
    const db = await getKnex();
    const comptes = await compterTables(db);
    const nonVides = TABLES.filter((definition) => comptes[definition.nom] > 0).map(
      (definition) => definition.nom
    );
    const refusCible = messageCibleNonVide(nonVides);
    if (refusCible) {
      console.error(refusCible);
      return 1;
    }
    console.log('Base cible : vide');

    if (!apply) {
      afficherPlan(fichier);
      console.log('DRY-RUN : aucune donnée écrite. Relancez avec --apply pour écrire.');
      return 0;
    }

    await alignerIdentites(db, fichier);
    console.log('Identités ré-alignées au-dessus des ids restaurés.');

    let total;
    try {
      total = await insererTout(db, fichier);
    } catch (err) {
      console.error(`Échec de la restauration : ${messageErreurOracle(err)}`);
      console.error('Transaction annulée : aucune donnée écrite. Ne retentez rien sans corriger la cause.');
      return 1;
    }
    console.log(`${total} ligne(s) insérée(s).`);

    const apres = await compterTables(db);
    const ecarts = TABLES.filter(
      (definition) => apres[definition.nom] !== fichier.counts[definition.nom]
    ).map(
      (definition) =>
        `${definition.nom} : ${fichier.counts[definition.nom]} attendu(s), ${apres[definition.nom]} présent(s)`
    );
    if (ecarts.length > 0) {
      console.error('Vérification des comptes en écart :');
      for (const ecart of ecarts) console.error(`  - ${ecart}`);
      return 1;
    }
    console.log('Restauration terminée : les 13 comptes correspondent à la sauvegarde.');
    return 0;
  } catch (err) {
    console.error(`Échec Oracle : ${messageErreurOracle(err)}`);
    return 1;
  } finally {
    try {
      await closeOracle();
    } catch {
      /* pool déjà fermé */
    }
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().then(
    (code) => process.exit(code),
    (err) => {
      console.error(`Échec de la restauration Oracle : ${err && err.message ? err.message : err}`);
      process.exit(1);
    }
  );
}
